// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

export interface IcdReleasesOut {
  /** The classification doctors code in (setting icd_coding_system) */
  coding_system: "ICD-11" | "ICD-10";
  releases: IcdReleaseOut[];
  /** The attribution the ICD-11 licence requires on screens and reports that use it */
  icd11_citation: string;
}

export interface IcdReleaseOut {
  release_id: number;
  code_system: "ICD-11" | "ICD-10";
  /** e.g. "2026-01" (ICD-11) or "2019" (ICD-10) */
  release_label: string;
  language: string;
  /** Bundled: shipped with the product (ICD-11); Imported: loaded by the hospital (its licensed ICD-10, or a newer ICD-11) */
  source: "Bundled" | "Imported";
  source_file: string | null;
  source_sha256: string | null;
  /** The licence the list is used under; show it where the list is used */
  licence_note: string;
  /** Codable categories */
  code_count: number;
  /** The list the picker searches and new codes are checked against */
  is_active: boolean;
  loaded_by: number | null;
  loaded_by_name: string | null;
  loaded_at: string;
  row_version: number;
}

export interface IcdReleaseLoadedOut {
  /** The classification doctors code in (setting icd_coding_system) */
  coding_system: "ICD-11" | "ICD-10";
  releases: IcdReleaseOut[];
  /** The attribution the ICD-11 licence requires on screens and reports that use it */
  icd11_citation: string;
  loaded: IcdReleaseOut;
}

/** The ICD code lists loaded — GET /api/v1/icd/releases (who may call: any logged-in user). */
export function releases(): Promise<IcdReleasesOut> {
  return api<IcdReleasesOut>("GET", `/icd/releases`, undefined);
}

/** Load an ICD code list (the hospital's licensed ICD-10, or a newer WHO ICD-11 release) — POST /api/v1/icd/releases (who may call: holders of icd.release.manage). */
export function loadRelease(body: FormData): Promise<IcdReleaseLoadedOut> {
  return api<IcdReleaseLoadedOut>("POST", `/icd/releases`, body);
}

/** Make a release the active list of its classification — POST /api/v1/icd/releases/{release_id}/activate (who may call: holders of icd.release.manage). */
export function activate(release_id: number): Promise<IcdReleasesOut> {
  return api<IcdReleasesOut>("POST", `/icd/releases/${release_id}/activate`, undefined);
}
